import socket
import select
import threading
import time
from socket import error as socket_error
from six.moves import queue as Queue
from six import string_types
import abc
import sys
from ta_emss.utilities.trs.err_transport import (ErrTransportTimeout, ErrTransportRecvQueueNotRegistered,
                                                 ErrRemoteEndpointDisconnected, ErrRemoteEndpointDead)


class TransportMedium(object):
    __metaclass__ = abc.ABCMeta

    def __init__(self, logger=None, data_logger=None):
        super(TransportMedium, self).__init__()
        self.logger = logger
        self.data_logger = data_logger

    def logger_debug_event(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_event(*args, **kwargs)
            except Exception as exc:
                print("[EXC] TransportMedium::logger_debug_event: %s" % exc)

    def logger_debug_print(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_print(*args, **kwargs)
            except Exception as exc:
                print("[EXC] TransportMedium::logger_debug_print: %s" % exc)

    def logger_debug_msg_flow(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_msg_flow(*args, **kwargs)
            except Exception as exc:
                print("[EXC] TransportMedium::logger_debug_msg_flow: %s" % exc)

    def logger_debug_high_priority(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_high_priority(*args, **kwargs)
            except Exception as exc:
                print("[EXC] TransportMedium::logger_debug_high_priority: %s" % exc)

    def data_logger_info(self, *args, **kwargs):
        if self.data_logger:
            try:
                self.data_logger.info(*args, **kwargs)
            except Exception as exc:
                print("[EXC] TransportMedium::data_logger_info: %s" % exc)

    @abc.abstractmethod
    def open(self):
        """
        Abstract open method
        """
        return

    @abc.abstractmethod
    def close(self):
        """
        Abstract close method
        """
        return

    @abc.abstractmethod
    def send(self, data):
        """
        Abstract send method
        """
        return

    def recv(self, timeout=30):
        data = None
        return data


class TCPTransportMedium(TransportMedium):
    def __init__(self, port, host="localhost", receiveBufferSize=64 * 4096, logger=None, data_logger=None):
        super(TCPTransportMedium, self).__init__()
        self.host = host
        self.port = port
        self.receiveBufferSize = receiveBufferSize
        self.logger = logger
        self.data_logger = data_logger
        self.socket = None
        self.blocking = 1
        self.logger_debug_event(info="CONSTRUCTED", owner="{{%s}}" % self.__class__.__name__)

    def __del__(self):
        self.logger_debug_event(info="DELETED", owner="{{%s}}" % self.__class__.__name__)

    def reopen(self, number_of_retries):
        for i in range(number_of_retries):
            time.sleep(1)
            self.logger_debug_print(info=str(i) + " retry to reconnect", owner="{{%s}}" % self.__class__.__name__)
            try:
                self.open()
                self.logger_debug_print(info="Server reconnected", owner="{{%s}}" % self.__class__.__name__)
                return 1
            except socket_error as serr:
                print("[EXC] TCPTransportMedium::reopen: Socket error: %s" % serr)
                if (serr.errno == 10061):
                    self.logger_debug_print(info="Retry to connect, echo server is still down",
                                            owner="{{%s}}" % self.__class__.__name__)
                else:
                    print("[RAI] TCPTransportMedium::reopen: Socket error")
                    raise

    def open(self):
        try:
            self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            if sys.platform.startswith('java'):  # Program runs under Jython
                self.blocking = 0  # Jython  limitation
            self.socket.setblocking(self.blocking)
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 4 * 1024 * 1024)
            self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 1 * 1024 * 1024)
            # FUTURE: maybe we change to non-blocking sockets on select inside threads
            #         but for now any call to RPC is blocking send-receive
            #             self.socket.setblocking(0)  # optional non-blocking
            #             CHECK_TIMEOUT = 0.01
            #             self.socket.settimeout(CHECK_TIMEOUT)
            self.socket.connect((self.host, self.port))
            self.logger_debug_event(info="OPEN: Connected to TCP %s:%s" % (self.host, self.port),
                                    owner="{{%s}}" % self.__class__.__name__)

        except Exception as exc:
            print("[EXC][RAI] TCPTransportMedium::open: %s" % exc)
            raise

    def close(self):
        if self.socket is not None:
            self.socket.close()
            self.socket = None
            self.logger_debug_event(info="CLOSED", owner="{{%s}}" % self.__class__.__name__)

    def send(self, data):
        try:
            debug_info = "CANNOT send"
            ready = select.select([], [self.socket], [], 0.01)
            if ready[1]:
                if isinstance(data, string_types):
                    self.socket.send(data.encode('utf-8'))
                else:
                    self.socket.send(data)
                debug_info = "send"
            msg_len = len(data) if data else 0
            self.logger_debug_msg_flow(info="%s: (%d)" % (debug_info, msg_len), data=data, owner="{{%s}}" % self.__class__.__name__)
        except socket_error as serr:
            print("[EXC][RAI] TCPTransportMedium::send: Socket error: %s" % serr)
            if (serr.errno == 10054) or (serr.errno == 10053):
                raise ErrRemoteEndpointDisconnected(
                    "[Transport Layer] Remote Endpoint Closed detected during send msg '%s'" % data)
            else:
                raise

    def recv(self, timeout=30):
        ready = [False]
        try:
            ready = select.select([self.socket], [], [], timeout)
        except TypeError as exc:
            # Fix for None type object is not callable during server shutdown
            print("[EXC] TCPTransportMedium::recv: TypeError: %s (timeout=%s)" % (exc, timeout))
            return

        if ready[0]:
            data = None
            try:
                data = self.socket.recv(self.receiveBufferSize)
                msg_len = 0
                try:
                    msg_len = len(data)
                except Exception as exc:
                    print("[EXC] TCPTransportMedium::recv: Cannot receive: %s (timeout=%s)" % (exc, timeout))
                self.logger_debug_msg_flow(info="recv: (%d)" % msg_len, data=data, owner="{{%s}}" % self.__class__.__name__)
            # error 10035 is no data available, it is non-fatal
            except socket_error as serr:
                print("[EXC][RAI] TCPTransportMedium::recv: Socket error: %s (timeout=%s)" % (serr, timeout))
                if (serr.errno == 10054) or (serr.errno == 10053):
                    raise ErrRemoteEndpointDisconnected("[Transport Layer] Remote Endpoint Closed Socket Gently")
                elif (serr.errno == 10061):
                    raise ErrRemoteEndpointDead("[Transport Layer] Remote Endpoint Terminated")
                else:
                    raise serr
            else:
                if not data:
                    print("[RAI] TCPTransportMedium::recv: No data (timeout=%s)" % timeout)
                    raise ErrRemoteEndpointDisconnected("[Transport Layer] Remote Endpoint Closed Socket Gently")

            return data
        else:
            if timeout > 0.02:
                print("[RAI] TCPTransportMedium::recv: ErrTransportTimeout (timeout=%s)" % timeout)
            raise ErrTransportTimeout("Timeout (> %.3f sec) on TCPTransportMedium host: %s port: %s" % (timeout, self.host, self.port))


class JsonMsgTransport(TransportMedium):  # Transport Client
    def __init__(self, port, host, logger, data_logger=None):
        super(JsonMsgTransport, self).__init__()
        self.embedded_transport = TCPTransportMedium(port=port, host=host, logger=logger)
        self.host = host
        self.port = port
        self.logger = logger
        self.data_logger = data_logger
        self.nonparsed_stream = ''
        self.json_msgs = []  # processed complete JSON msgs
        self.json_part_msgs = []
        self.logger_debug_event(info="CONSTRUCTED", owner="{%s}" % self.__class__.__name__)

    def __del__(self):
        self.logger_debug_event(info="DELETED", owner="{%s}" % self.__class__.__name__)

    def open(self):
        self.data_logger_info('##:LOG:############################################################################', extra={'pkg_type': 'S'})
        self.data_logger_info('', extra={'pkg_type': 'O'})
        return self.embedded_transport.open()

    def close(self):
        return self.embedded_transport.close()

    def send(self, data):
        data = self._encode_json_to_netstring(data)
        self.data_logger_info(data, extra={'direction': '>'})
        self.logger_debug_msg_flow(info="send:", data=data,
                                   owner="{{%s}}" % self.__class__.__name__)
        self.embedded_transport.send(data)

    def recv(self, timeout=30):
        # first try buffered data
        if len(self.json_msgs):
            msg = self.json_msgs.pop(0)
            self.data_logger_info(msg, extra={'direction': '<'})
            return msg
        # if none then read
        start_time = time.time()
        remaining_time = timeout
        while remaining_time > 0:
            json_chunk = self.embedded_transport.recv(remaining_time)
            if json_chunk:
                self.logger_debug_msg_flow(info="receive:", data=json_chunk,
                                           owner="{{%s}}" % self.__class__.__name__)
                self._decode_netstring_to_json(json_chunk)
                if len(self.json_msgs):
                    msg = self.json_msgs.pop(0)
                    self.data_logger_info(msg, extra={'direction': '<'})
                    return msg
            remaining_time = timeout - (time.time() - start_time)

        print("[RAI] JsonMsgTransport::recv: ErrTransportTimeout (timeout=%s)" % timeout)
        raise ErrTransportTimeout("Timeout on JsonMsgTransport")

    def _decode_netstring_to_json(self, json):
        while json != b'':
            if not self.json_part_msgs:
                (presep, sep, postsep) = json.partition(b":")
                try:
                    ns_length = int(presep.decode())
                except ValueError as e:
                    print("[EXC] JsonMsgTransport::_decode_netstring_to_json: %s" % e)
                    self.logger_debug_high_priority("Wrong netstring msg: {}".format(e))
                    break
                curr_length = len(postsep)
                if curr_length > ns_length:
                    if postsep[ns_length:ns_length + 1] == b',':
                        data = postsep[:ns_length]
                        self.json_msgs.append(data.decode('utf-8', 'replace'))
                        json = postsep[ns_length + 1:]  # cut coma
                    elif len(postsep[ns_length:]) >= 1:
                        self.logger_debug_high_priority("Wrong netstring msg")
                        json = postsep[ns_length:]
                else:
                    self.json_part_msgs.append(json)
                    json = b''
            else:
                prev_msg = self.json_part_msgs.pop()
                json = prev_msg + json

    def _encode_json_to_netstring(self, json_msg):
        try:
            binmsg = json_msg.encode('utf-8')
        except Exception as exc:
            print("[EXC] JsonMsgTransport::_encode_json_to_netstring: %s" % exc)
            binmsg = json_msg.encode('ascii', 'ignore')

        netstring = str(len(binmsg)).encode() + b':' + binmsg + b','
        return netstring


class JsonThreadedTransportMedium(TransportMedium):
    def __init__(self, port, host, logger, data_logger):
        super(JsonThreadedTransportMedium, self).__init__()

        self.embedded_transport = JsonMsgTransport(port=port, host=host, logger=logger, data_logger=data_logger)
        self.logger = logger
        self.server = None
        self.goOnEvent = None
        self.sendQueue = Queue.Queue()
        self.recvQueue = Queue.Queue()
        self.logger_debug_event(info="CONSTRUCTED", owner="{%s}" % self.__class__.__name__)

    def __del__(self):
        self.logger_debug_event(info="DELETED", owner="{%s}" % self.__class__.__name__)

    def is_running(self):
        return self.server.is_running()

    def open(self, goOnEvent=None):
        if goOnEvent is None:
            self.goOnEvent = threading.Event()
            self.goOnEvent.set()
        else:
            self.goOnEvent = goOnEvent
        self.server = ThreadedTransportServer(self.goOnEvent,
                                              self.sendQueue,
                                              self.recvQueue,
                                              self.embedded_transport,
                                              self.logger,
                                              name="TransportSvr")
        self.server.daemon = True
        self.server.start()
        self.logger_debug_event(info="OPEN", owner="{%s}" % self.__class__.__name__)

    def close(self):
        self.goOnEvent.clear()
        self.server.join()
        self.logger_debug_event(info="CLOSED", owner="{%s}" % self.__class__.__name__)

    def send(self, data):
        self.sendQueue.put(data)
        self.logger_debug_msg_flow(info="Inserted into sendQueue:", data=data,
                                   owner="{%s}" % self.__class__.__name__)

    def recv(self, timeout=30):
        try:
            # if self.recvQueue.empty():
            #     return None
            (data, error) = self.recvQueue.get(block=True, timeout=timeout)
            self.logger_debug_msg_flow(info="Got from recvQueue:", data=(data, error),
                                       owner="{%s}" % self.__class__.__name__)
            if error:
                print("[EXC][RAI] JsonThreadedTransportMedium::recv: Error getting from queue: %s" % error)
                raise error
                # reconnection if there is "Echo server down" in queue
                # if data == "Echo server down":
                # self.embedded_transport.reopen(5)
            return data
        except Queue.Empty:
            if timeout > 0.02:
                print("[EXC][RAI] JsonThreadedTransportMedium::recv: Queue.Empty -> ErrTransportTimeout (timeout=%s)" % timeout)
            data = None
            # we need exception here since data == None may be valid value
            # and moreover, our requirement is to raise it when timeout expires
            raise ErrTransportTimeout("Timeout on recvQueue from ThreadedServer (%s)" % timeout)
        except AttributeError as exc:
            print("[EXC][RAI] JsonThreadedTransportMedium::recv: AttributeError -> ErrTransportRecvQueueNotRegistered (timeout=%s)" % timeout)
            raise ErrTransportRecvQueueNotRegistered(exc)
        except TypeError:
            # Get rid of 'NoneType' object is not callable in threading module while emss teardown
            print("[EXC] JsonThreadedTransportMedium::recv: TypeError")


class ThreadedTransportServer(threading.Thread):  # Transport Server
    def __init__(self, goOnEvent,
                 sendQueue,
                 recvQueue,
                 embedded_transport,
                 logger,
                 name):
        super(ThreadedTransportServer, self).__init__(name=name)
        self.goOnEvent = goOnEvent
        self.sendQueue = sendQueue
        self.recvQueue = recvQueue
        self.embedded_transport = embedded_transport
        self.logger = logger
        self.receiveBufferSize = 1024
        self.logger_debug_event(info="CONSTRUCTED", owner="{%s}" % self.__class__.__name__)

    def logger_debug_event(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_event(*args, **kwargs)
            except Exception as exc:
                print("[EXC] ThreadedTransportServer::logger_debug_event: %s" % exc)

    def logger_debug_msg_flow(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_msg_flow(*args, **kwargs)
            except Exception as exc:
                print("[EXC] ThreadedTransportServer::logger_debug_msg_flow: %s" % exc)

    def logger_debug_high_priority(self, *args, **kwargs):
        if self.logger:
            try:
                self.logger.debug_high_priority(*args, **kwargs)
            except Exception as exc:
                print("[EXC] ThreadedTransportServer::logger_debug_high_priority: %s" % exc)

    def __del__(self):
        self.logger_debug_event(info="DELETED", owner="{%s}" % self.__class__.__name__)

    def is_running(self):
        return self.goOnEvent.is_set()

    def run(self):
        try:
            self.embedded_transport.open()
        except socket_error as serr:
            print("[EXC][RAI] ThreadedTransportServer::run: Socket error: %s" % serr)
            print("!" * 100)
            print("*ERROR* SocketError: Cannot open connnection to host: %s, port: %s (%s)" %
                  (self.embedded_transport.host, self.embedded_transport.port, str(serr)))
            print("!" * 100)
            time.sleep(5)
            raise serr
        except Exception as exc:
            print("[EXC][RAI] ThreadedTransportServer::run: %s" % exc)
            print("*ERROR* ConnectionError: Cannot open connnection to host: %s, port: %s (%s)" %
                  (self.embedded_transport.host, self.embedded_transport.port, str(exc)))
            raise exc
        else:
            try:
                self._data_recv()
            finally:
                self.embedded_transport.close()
        finally:
            self.goOnEvent.clear()
            self.logger_debug_event(info="FINISHED", owner="{%s}" % self.__class__.__name__)

    def _data_recv(self):
        while self.goOnEvent.is_set():
            if not self._data_from_send_to_recv_queue():
                break
            if not self._data_from_transport_to_recv_queue():
                break

    def _data_from_send_to_recv_queue(self):
        try:
            if self.sendQueue.empty():
                return True
            data = self.sendQueue.get(block=True, timeout=0.01)
            if data:
                self.logger_debug_msg_flow(info="Send via embedded transport:", data=data,
                                           owner="{%s}" % self.__class__.__name__)
                self.embedded_transport.send(data)
        except Queue.Empty:
            print("[EXC] ThreadedTransportServer::_data_from_send_to_recv_queue: Queue.Empty")
        except TypeError:
            # Get rid of 'NoneType' object is not callable in threading module while emss teardown
            print("[EXC] ThreadedTransportServer::_data_from_send_to_recv_queue: TypeError")
        except AttributeError:
            # Get rid of 'NoneType' object has no attribute 'Empty' in TransportSvr during interpreter shutdown
            print("[EXC] ThreadedTransportServer::_data_from_send_to_recv_queue: AttributeError")
        except ErrRemoteEndpointDisconnected as exc:
            print("[EXC] ThreadedTransportServer::_data_from_send_to_recv_queue: %s" % exc)
            self.logger_debug_high_priority(info="Remote Endpoint Disconnected [error info]:",
                                            data=exc.err, owner="{%s}" % self.__class__.__name__)
            self.recvQueue.put((None, exc))
            return False
        return True

    def _data_from_transport_to_recv_queue(self):
        (data, error) = (None, None)
        try:
            data = self.embedded_transport.recv(timeout=0.01)
            self.logger_debug_msg_flow(info="Message got from embedded transport:", data=data,
                                       owner="{%s}" % self.__class__.__name__)
            self.recvQueue.put((data, error))
        except ErrRemoteEndpointDisconnected as exc:
            print("[EXC] ThreadedTransportServer::_data_from_transport_to_recv_queue: ErrRemoteEndpointDisconnected (%s)" % exc)
            self.logger_debug_high_priority(info="Remote Endpoint Disconnected [error info]:",
                                            data=exc.err, owner="{%s}" % self.__class__.__name__)
            self.recvQueue.put((data, exc))
            return False
        except ErrRemoteEndpointDead as exc:
            print("[EXC] ThreadedTransportServer::_data_from_transport_to_recv_queue: ErrRemoteEndpointDead (%s)" % exc)
            self.logger.debug_high_priority(info="Remote Endpoint Dead [error info]:", data=exc.err,
                                            owner="{%s}" % self.__class__.__name__)
            self.recvQueue.put((data, exc))
            return False
        except TypeError:
            # Fix for exception during server shutdown
            print("[EXC] ThreadedTransportServer::_data_from_transport_to_recv_queue: TypeError")
        except ErrTransportTimeout:
            # print("[EXC] ThreadedTransportServer::_data_from_transport_to_recv_queue: ErrTransportTimeout")
            pass
        return True
